INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(1,'qData 功能升级！数据集成更高效','1',0x3C703E714461746120E58A9FE883BDE58D87E7BAA7EFBC81E695B0E68DAEE99B86E68890E69BB4E9AB98E695883C2F703E,'0','admin',' 2025-05-29 11:32:05.000000000','admin',' 2025-06-20 15:15:15.000000000',null,0,0,null,null,null);
