INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(3,'主数据管理平台正式上线运行通知','1',null,'0','系统管理员',' 2026-09-29 09:00:00.000000000','admin',' 2026-09-29 14:25:20.000000000','平台运行通知',1,0,' 2026-09-29 09:00:00.000000000',' 2026-10-15 18:00:00.000000000','<h2>主数据管理平台正式上线</h2><p>为统一集团客户、供应商、产品物料、组织人员等核心主数据，自2026年9月29日起，主数据管理平台正式投入运行。</p><h3>业务办理要求</h3><ul><li>新增或变更核心主数据，应通过平台发起申请并完成审批。</li><li>各业务系统原则上不再自行新增主数据编码。</li><li>数据责任人应及时处理待办事项，确保业务数据准确、完整、有效。</li></ul><p><strong>适用范围：</strong>集团总部、各分子公司及接入主数据服务的业务系统。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(4,'客户主数据标准V1.0正式发布公告','2',null,'0','数据治理办公室',' 2026-09-28 14:30:00.000000000','数据治理办公室',' 2026-09-28 14:30:00.000000000','客户主数据标准',1,0,null,null,'<h2>客户主数据标准V1.0发布</h2><p>客户主数据标准V1.0已经数据治理委员会审议通过，现正式发布。</p><h3>标准范围</h3><ul><li>客户统一编码、客户名称和统一社会信用代码。</li><li>客户类型、信用等级和生命周期状态。</li><li>客户归属组织、客户经理、地址及联系人信息。</li></ul><p>各业务部门应按照标准采集和维护客户数据；各接入系统应以主数据平台发布的客户编码作为跨系统关联标识。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(5,'2026年度供应商资质集中复核通知','1',null,'0','采购管理中心',' 2026-09-27 10:00:00.000000000','admin',' 2026-09-29 14:25:29.000000000','供应商资质管理',0,0,' 2026-10-01 08:00:00.000000000',' 2026-10-31 18:00:00.000000000','<h2>供应商资质集中复核安排</h2><p>采购管理中心将于2026年10月开展年度供应商资质集中复核。</p><h3>复核内容</h3><ul><li>营业执照、行业许可证及体系认证证书。</li><li>收款账户、联系人和注册地址。</li><li>供应商等级、准入状态及历史履约情况。</li></ul><p><strong>完成时限：</strong>2026年10月31日18:00前。</p><p>证照已过期或信息不完整的供应商，将暂停新增采购业务。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(6,'产品物料统一编码规范发布公告','2',null,'0','产品数据管理组',' 2026-09-26 16:00:00.000000000','产品数据管理组',' 2026-09-26 16:00:00.000000000','产品物料编码规范',0,0,null,null,'<h2>产品物料统一编码规范</h2><p>为解决多系统产品物料编码不一致问题，产品物料统一编码规范即日起执行。</p><ul><li>产品编码由主数据平台按照编码方案自动生成。</li><li>产品必须归属到末级产品品类。</li><li>基本计量单位应从标准参考数据中选择。</li><li>同一产品可以维护多个条码和多个包装规格。</li></ul><p>采购、库存、销售和财务系统应统一使用平台发布的产品编码。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(7,'组织与人员主数据同步机制公告','2',null,'0','人力资源中心',' 2026-09-25 11:20:00.000000000','人力资源中心',' 2026-09-25 11:20:00.000000000','组织人员数据同步',0,0,null,null,'<h2>组织与人员数据同步机制</h2><p>组织架构和员工主数据由人力资源系统归口维护，通过主数据平台统一向各业务系统发布。</p><h3>同步规则</h3><ul><li>组织新增、合并、撤销经审批后进入主数据平台。</li><li>员工入职、转岗、离职信息按业务事件同步。</li><li>各系统通过组织编码和员工编码建立关联。</li><li>业务系统不得自行修改组织层级和员工在职状态。</li></ul>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(8,'主数据平台月度维护窗口通知','1',null,'0','平台运维中心',' 2026-09-24 17:30:00.000000000','平台运维中心',' 2026-09-24 17:30:00.000000000','系统维护安排',0,0,null,null,'<h2>月度维护窗口安排</h2><p>主数据平台计划于2026年10月11日00:00至03:00进行月度维护。</p><ul><li>维护期间平台页面可能短时无法访问。</li><li>主数据查询接口保持服务，发布和变更接口可能短时暂停。</li><li>维护完成后，未处理完毕的申请可继续办理。</li></ul><p>请各业务部门提前安排批量导入和集中审批工作。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(9,'第三季度主数据权限复核通知','1',null,'0','信息安全部',' 2026-09-23 09:15:00.000000000','信息安全部',' 2026-09-23 09:15:00.000000000','数据权限复核',0,0,null,null,'<h2>主数据权限季度复核</h2><p>请各部门数据责任人完成第三季度主数据访问权限复核。</p><ul><li>核对本部门用户、角色和数据范围。</li><li>及时移除离岗、转岗人员不再需要的权限。</li><li>确认新增权限均有有效申请和审批记录。</li><li>重点复核批量导出、批量维护和授权管理权限。</li></ul><p><strong>反馈时限：</strong>2026年10月10日前。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(10,'2026年9月主数据质量运行情况公告','2',null,'0','数据治理办公室',' 2026-09-22 15:00:00.000000000','数据治理办公室',' 2026-09-22 15:00:00.000000000','主数据质量月报',0,0,null,null,'<h2>2026年9月主数据质量运行情况</h2><ul><li>客户主数据完整率：98.6%。</li><li>供应商资质有效率：97.9%。</li><li>产品物料品类归属准确率：99.2%。</li><li>组织人员数据同步及时率：99.7%。</li></ul><p>本月主要问题集中在客户联系方式缺失、供应商证照临近到期和历史产品计量单位不统一。相关责任部门应按照质量问题清单完成整改。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(11,'供应商编码规则调整公告','2',null,'0','数据标准管理组',' 2026-09-20 10:30:00.000000000','数据标准管理组',' 2026-09-20 10:30:00.000000000','编码规则调整',0,0,null,null,'<h2>供应商编码规则调整</h2><p>供应商编码统一调整为“SUP + 建档日期 + 5位流水号”，新规则自2026年10月1日起执行。</p><ul><li>历史供应商编码保持不变。</li><li>新建供应商由平台自动生成编码。</li><li>编码一经发布不得手工修改或重复使用。</li><li>业务系统应同时保留历史编码映射关系。</li></ul>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(12,'核心主数据责任体系公告','2',null,'0','数据治理委员会',' 2026-09-18 09:00:00.000000000','数据治理委员会',' 2026-09-18 09:00:00.000000000','数据责任体系',0,0,null,null,'<h2>核心主数据责任体系</h2><ul><li><strong>客户主数据：</strong>市场运营中心负责标准和质量，销售单位负责数据维护。</li><li><strong>供应商主数据：</strong>采购管理中心负责准入、分级和资质管理。</li><li><strong>产品物料主数据：</strong>产品数据管理组负责品类、编码和标准属性。</li><li><strong>组织人员主数据：</strong>人力资源中心负责组织架构和员工状态。</li></ul><p>数据治理办公室负责跨域协调、质量监督和标准变更管理。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(13,'客户历史数据集中治理工作通知','1',null,'1','数据治理办公室',' 2026-08-10 09:00:00.000000000','数据治理办公室',' 2026-09-01 18:00:00.000000000','治理工作已完成',0,0,null,null,'<h2>客户历史数据集中治理</h2><p>本次治理范围包括重复客户合并、统一社会信用代码补录、客户名称规范化和失效客户清理。</p><p>集中治理工作已于2026年8月31日完成，后续问题转入常态化质量管理流程。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(14,'主数据服务接口切换通知','1',null,'1','平台运维中心',' 2026-08-01 13:00:00.000000000','平台运维中心',' 2026-08-16 09:00:00.000000000','接口切换已完成',0,1,' 2026-08-10 08:00:00.000000000',' 2026-08-15 23:59:59.000000000','<h2>主数据服务接口切换</h2><p>客户、供应商和产品物料查询接口已切换至统一主数据服务网关。</p><p>接口地址、认证方式和返回结构保持兼容，原接口已于2026年8月15日停止服务。本次切换工作已完成。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(15,'功能说明｜主数据域管理','2',null,'1','平台运营中心',' 2026-09-29 09:00:00.000000000','平台运营中心',' 2026-09-29 09:00:00.000000000','模块功能说明',1,0,null,null,'<h2>主数据域管理</h2><p>主数据域用于按照企业业务边界组织和管理核心主数据，是模型、目录和权责划分的顶层入口。</p><h3>核心能力</h3><ul><li>维护主数据域编码、名称、说明和启用状态。</li><li>集中查看域内模型目录、模型数量和关联模型。</li><li>为客户、供应商、产品物料、组织人员等主题建立独立管理边界。</li><li>支持从主数据域详情进入目录和模型配置。</li></ul><p><strong>典型用法：</strong>先创建“客户主数据域”，再在域内建立客户档案目录和客户模型。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(16,'功能说明｜模型目录管理','2',null,'1','平台运营中心',' 2026-09-29 09:05:00.000000000','平台运营中心',' 2026-09-29 09:05:00.000000000','模块功能说明',1,0,null,null,'<h2>模型目录管理</h2><p>模型目录用于对同一主数据域下的模型进行分层分类，帮助业务人员快速理解模型归属。</p><h3>核心能力</h3><ul><li>支持多级目录、新增子级、修改、删除和排序。</li><li>支持目录树展开、折叠和批量维护。</li><li>统计目录下的模型数量，防止误删已被模型引用的目录。</li><li>模型设计时可直接选择所属目录。</li></ul><p><strong>典型用法：</strong>在产品物料域下建立“产品品类”“产品档案”“包装与条码”等目录。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(17,'功能说明｜参考数据管理','2',null,'1','平台运营中心',' 2026-09-29 09:10:00.000000000','平台运营中心',' 2026-09-29 09:10:00.000000000','模块功能说明',1,0,null,null,'<h2>参考数据管理</h2><p>参考数据用于统一业务字段的可选值，避免不同系统对同一状态、类型或等级使用不同编码。</p><h3>核心能力</h3><ul><li>维护参考数据类型及其编码、名称和说明。</li><li>在类型下维护数据项编码、名称、排序和启用状态。</li><li>查看参考数据被哪些模型字段使用。</li><li>模型字段绑定后，主数据维护页面自动使用标准选项。</li></ul><p><strong>典型用法：</strong>建立客户类型、供应商等级、产品计量单位和员工状态等标准数据项。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(18,'功能说明｜编码方案管理','2',null,'1','平台运营中心',' 2026-09-29 09:15:00.000000000','平台运营中心',' 2026-09-29 09:15:00.000000000','模块功能说明',0,0,null,null,'<h2>编码方案管理</h2><p>编码方案用于统一生成客户、供应商、产品和员工等主数据业务编码。</p><h3>核心能力</h3><ul><li>组合固定文本、业务字段、参考数据映射、日期时间和流水号规则段。</li><li>支持规则排序、结构预览和编码试算。</li><li>支持流水号位数、起始值、步长、补位和重置周期配置。</li><li>通过版本管理控制草稿、发布和停用状态。</li></ul><p><strong>典型用法：</strong>“SUP + 建档日期 + 5位流水号”可生成SUP2026092900001。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(19,'功能说明｜主数据模型设计','2',null,'1','平台运营中心',' 2026-09-29 09:20:00.000000000','平台运营中心',' 2026-09-29 09:20:00.000000000','模块功能说明',0,0,null,null,'<h2>主数据模型设计</h2><p>主数据模型定义业务对象的字段结构、约束、关系和物理存储方式。</p><h3>核心能力</h3><ul><li>支持普通模型和树形分类模型。</li><li>支持系统字段、普通业务字段、普通关联字段和分类字段。</li><li>配置数据类型、长度、精度、必填、唯一、名称字段和默认值。</li><li>字段可绑定参考数据或自动编码方案。</li><li>主模型可增加多级子模型，表达地址、联系人、证照等一对多数据。</li></ul><p><strong>典型用法：</strong>客户主模型下配置地址和联系人子模型，并关联组织分类及客户经理。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(20,'功能说明｜模型关联配置','2',null,'1','平台运营中心',' 2026-09-29 09:25:00.000000000','平台运营中心',' 2026-09-29 09:25:00.000000000','模块功能说明',0,0,null,null,'<h2>模型关联配置</h2><p>模型关联用于描述不同主数据对象之间的业务关系，形成可追溯的主数据关系网络。</p><h3>核心能力</h3><ul><li>普通关联字段可绑定目标模型、关联键字段和展示字段。</li><li>分类字段可绑定分类模型，并设置任意节点或仅叶子节点。</li><li>分类字段支持显示节点名称或完整路径。</li><li>关联关系可用于表单选择、详情展示和下游数据发布。</li></ul><p><strong>典型用法：</strong>产品关联首选供应商，客户关联客户经理，员工关联直属上级。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(21,'功能说明｜模型版本与发布','2',null,'1','平台运营中心',' 2026-09-29 09:30:00.000000000','平台运营中心',' 2026-09-29 09:30:00.000000000','模块功能说明',1,0,null,null,'<h2>模型版本与发布</h2><p>模型版本用于管理字段结构变化并保证正式运行模型稳定可追溯。</p><h3>核心能力</h3><ul><li>保存模型草稿并记录字段结构。</li><li>支持模型发布、修订、停用和版本查看。</li><li>对比不同版本的模型属性与字段变化。</li><li>发布时同步生成主模型及子模型物理实例。</li><li>正式版本与物理表、数据源保持明确关联。</li></ul><p><strong>典型用法：</strong>新增字段时创建修订版本，确认影响后发布为新的正式版本。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(22,'功能说明｜数据源管理','2',null,'1','平台运营中心',' 2026-09-29 09:35:00.000000000','平台运营中心',' 2026-09-29 09:35:00.000000000','模块功能说明',1,0,null,null,'<h2>数据源管理</h2><p>数据源管理统一维护平台接入和发布数据所需的数据库连接。</p><h3>核心能力</h3><ul><li>维护数据源名称、类型、地址、端口和连接配置。</li><li>支持主流关系型数据库连接。</li><li>提供连接校验和可用状态管理。</li><li>为数据接入任务和模型物化提供目标数据源。</li></ul><p><strong>典型用法：</strong>配置业务系统来源库和主数据权威库，分别用于数据接入和正式模型发布。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(23,'功能说明｜来源系统管理','2',null,'1','平台运营中心',' 2026-09-29 09:40:00.000000000','平台运营中心',' 2026-09-29 09:40:00.000000000','模块功能说明',0,0,null,null,'<h2>来源系统管理</h2><p>来源系统用于登记向主数据平台提供数据的业务系统及其责任信息。</p><h3>核心能力</h3><ul><li>维护系统编码、名称、责任部门和责任人。</li><li>关联一个或多个数据源。</li><li>标识来源系统涉及的主数据模型。</li><li>查看系统接入记录和数据来源范围。</li></ul><p><strong>典型用法：</strong>将CRM登记为客户数据来源，将ERP登记为供应商和产品物料数据来源。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(24,'功能说明｜数据接入任务','2',null,'1','平台运营中心',' 2026-09-29 09:45:00.000000000','平台运营中心',' 2026-09-29 09:45:00.000000000','模块功能说明',0,0,null,null,'<h2>数据接入任务</h2><p>数据接入任务负责将来源系统数据按规则同步到主数据处理链路。</p><h3>核心能力</h3><ul><li>选择来源系统、数据源和目标主数据模型。</li><li>配置来源表、字段映射、转换规则和同步方式。</li><li>支持全量和增量接入策略。</li><li>查看任务状态、执行记录、同步数量和错误信息。</li><li>接入数据可继续进入匹配、归并和质量处理。</li></ul><p><strong>典型用法：</strong>每日增量同步CRM客户和ERP供应商数据。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(25,'功能说明｜来源记录管理','2',null,'1','平台运营中心',' 2026-09-29 09:50:00.000000000','平台运营中心',' 2026-09-29 09:50:00.000000000','模块功能说明',0,0,null,null,'<h2>来源记录管理</h2><p>来源记录用于查看各业务系统接入平台的原始主数据及处理状态。</p><h3>核心能力</h3><ul><li>按来源系统、模型、批次和接入时间查询。</li><li>查看原始字段值和标准字段映射结果。</li><li>识别待匹配、待归并、处理完成或失败记录。</li><li>保留来源标识，支持权威数据反向追溯。</li></ul><p><strong>典型用法：</strong>从权威客户记录追溯其CRM、ERP等来源系统中的原始数据。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(26,'功能说明｜匹配规则管理','2',null,'1','平台运营中心',' 2026-09-29 09:55:00.000000000','平台运营中心',' 2026-09-29 09:55:00.000000000','模块功能说明',1,0,null,null,'<h2>匹配规则管理</h2><p>匹配规则用于判断不同来源记录是否代表同一个业务对象。</p><h3>核心能力</h3><ul><li>按主数据模型配置精确匹配和相似匹配条件。</li><li>支持多字段组合、权重、阈值和规则优先级。</li><li>可使用统一社会信用代码、名称、电话、地址等字段匹配。</li><li>规则启停后影响后续匹配任务，不改变历史结果。</li></ul><p><strong>典型用法：</strong>客户证照号码完全一致直接匹配；名称与地址达到相似度阈值时进入人工确认。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(27,'功能说明｜生存规则管理','2',null,'1','平台运营中心',' 2026-09-29 10:00:00.000000000','平台运营中心',' 2026-09-29 10:00:00.000000000','模块功能说明',1,0,null,null,'<h2>生存规则管理</h2><p>生存规则决定多条来源记录归并时，每个字段最终采用哪一个来源值。</p><h3>核心能力</h3><ul><li>按照来源系统优先级选择字段值。</li><li>支持最新值、最早值、非空值和人工指定等策略。</li><li>可对不同字段设置不同规则。</li><li>保留字段来源，便于解释最终结果。</li></ul><p><strong>典型用法：</strong>客户名称以工商系统为准，联系电话采用最近更新时间最新的非空值。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(28,'功能说明｜数据匹配检测','2',null,'1','平台运营中心',' 2026-09-29 10:05:00.000000000','平台运营中心',' 2026-09-29 10:05:00.000000000','模块功能说明',0,0,null,null,'<h2>数据匹配检测</h2><p>匹配检测按照匹配规则发现疑似相同的来源记录并形成候选分组。</p><h3>核心能力</h3><ul><li>选择模型和数据范围执行检测。</li><li>展示命中规则、匹配得分和字段对比。</li><li>区分确定匹配和需要人工判断的候选记录。</li><li>检测结果可进入归并处理或标记为非重复。</li></ul><p><strong>典型用法：</strong>发现不同系统中名称略有差异但证照和联系电话一致的供应商记录。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(29,'功能说明｜数据归并管理','2',null,'1','平台运营中心',' 2026-09-29 10:10:00.000000000','平台运营中心',' 2026-09-29 10:10:00.000000000','模块功能说明',0,0,null,null,'<h2>数据归并管理</h2><p>数据归并将多来源记录合成为一条完整、可信且可解释的主数据结果。</p><h3>核心能力</h3><ul><li>查看各来源记录的字段原值。</li><li>根据生存规则自动推荐最终字段值。</li><li>对冲突字段进行人工确认和调整。</li><li>确认后自动执行质量检测。</li><li>质量通过后提交审批，保留完整归并过程。</li></ul><p><strong>典型用法：</strong>将CRM和ERP中的同一客户合并为统一客户主数据。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(30,'功能说明｜数据质量规则','2',null,'1','平台运营中心',' 2026-09-29 10:15:00.000000000','平台运营中心',' 2026-09-29 10:15:00.000000000','模块功能说明',0,0,null,null,'<h2>数据质量规则</h2><p>质量规则用于定义主数据必须满足的完整性、唯一性、有效性、一致性和及时性要求。</p><h3>核心能力</h3><ul><li>配置非空、长度、格式、范围、唯一和跨字段校验。</li><li>规则可绑定主数据模型及具体字段。</li><li>支持启停、优先级和问题严重程度。</li><li>规则可被质量任务重复使用。</li></ul><p><strong>典型用法：</strong>校验统一社会信用代码长度和唯一性，检查证照到期日期是否早于生效日期。</p>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(31,'功能说明｜质量任务与问题整改','2',null,'1','平台运营中心',' 2026-09-29 10:20:00.000000000','平台运营中心',' 2026-09-29 10:20:00.000000000','模块功能说明',0,0,null,null,'<h2>质量任务与问题整改</h2><p>质量任务按照选定规则批量检查主数据，并将不符合要求的记录转化为质量问题。</p><h3>核心能力</h3><ul><li>选择模型、规则和数据范围创建检查任务。</li><li>支持手工执行和周期调度。</li><li>查看任务实例、通过率、问题数量和趋势。</li><li>质量问题可分派责任人、记录原因并跟踪整改状态。</li><li>问题详情定位到具体模型、记录、字段和规则。</li></ul>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(32,'功能说明｜权威主数据维护','2',null,'1','平台运营中心',' 2026-09-29 10:25:00.000000000','平台运营中心',' 2026-09-29 10:25:00.000000000','模块功能说明',1,0,null,null,'<h2>权威主数据维护</h2><p>权威主数据是经标准化、质量校验和审批确认后对外发布的可信数据。</p><h3>核心能力</h3><ul><li>按模型查看主数据列表和分类数据。</li><li>支持新增、修改、复制、批量更新和批量导入。</li><li>支持冻结、解冻、失效、恢复和归档等生命周期操作。</li><li>主模型详情中可维护地址、联系人等子模型记录。</li><li>操作可先保存为未提交申请，再进入审批流程。</li></ul>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(33,'功能说明｜我的申请与维护审批','2',null,'1','平台运营中心',' 2026-09-29 10:30:00.000000000','平台运营中心',' 2026-09-29 10:30:00.000000000','模块功能说明',1,0,null,null,'<h2>我的申请与维护审批</h2><p>申请审批模块用于控制主数据变更过程，确保关键数据经过责任人审核后生效。</p><h3>核心能力</h3><ul><li>查看草稿、已提交、审批中、通过和退回申请。</li><li>支持单条及批量新增、修改、导入和状态变更申请。</li><li>申请详情展示变更前后值、明细数量和申请原因。</li><li>审批人可查看业务内容并给出通过或退回意见。</li><li>审批结果与正式主数据、操作记录保持关联。</li></ul>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(34,'功能说明｜数据授权管理','2',null,'1','平台运营中心',' 2026-09-29 10:35:00.000000000','平台运营中心',' 2026-09-29 10:35:00.000000000','模块功能说明',0,0,null,null,'<h2>数据授权管理</h2><p>数据授权用于控制不同用户、角色和组织可查看或维护哪些主数据。</p><h3>核心能力</h3><ul><li>以主数据模型为授权单元选择授权主体。</li><li>支持全部数据或按条件限定数据范围。</li><li>可配置字段可见、字段脱敏和字段编辑权限。</li><li>可选择查看、新增、修改、导入、导出和生命周期操作。</li><li>支持授权有效期、批量授权、撤权和到期控制。</li></ul>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(35,'功能说明｜服务授权管理','2',null,'1','平台运营中心',' 2026-09-29 10:40:00.000000000','平台运营中心',' 2026-09-29 10:40:00.000000000','模块功能说明',0,0,null,null,'<h2>服务授权管理</h2><p>服务授权用于控制应用调用主数据服务的模型范围、字段范围和操作能力。</p><h3>核心能力</h3><ul><li>选择应用、服务和主数据模型建立授权。</li><li>限定允许调用、导出或批量调用的操作。</li><li>配置授权有效期和启用状态。</li><li>支持撤销授权并保留授权变更记录。</li><li>与数据授权共同构成用户访问和应用访问的双重控制。</li></ul>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(36,'功能说明｜操作审计','2',null,'1','平台运营中心',' 2026-09-29 10:45:00.000000000','平台运营中心',' 2026-09-29 10:45:00.000000000','模块功能说明',0,0,null,null,'<h2>操作审计</h2><p>操作审计记录用户在主数据平台中的关键业务操作，为安全检查和问题定位提供依据。</p><h3>核心能力</h3><ul><li>记录操作模块、功能、对象、类型、操作人和时间。</li><li>保存请求标识、访问地址、执行结果和异常信息。</li><li>支持按对象、用户、时间和结果查询。</li><li>详情可关联单条或多条业务对象。</li><li>审计记录只读保存，避免业务人员修改历史。</li></ul>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(37,'功能说明｜变更历史与数据版本','2',null,'1','平台运营中心',' 2026-09-29 10:50:00.000000000','平台运营中心',' 2026-09-29 10:50:00.000000000','模块功能说明',0,0,null,null,'<h2>变更历史与数据版本</h2><p>变更历史用于还原主数据每次变化的内容，数据版本用于查看特定时间点的完整状态。</p><h3>核心能力</h3><ul><li>记录新增、修改、归并和生命周期变更。</li><li>展示变更前值、变更后值、申请和操作人。</li><li>按主数据记录查看时间线。</li><li>支持不同数据版本之间的字段对比。</li><li>为争议处理、合规检查和问题回溯提供证据。</li></ul>');
INSERT INTO "QDATA_MDM"."SYSTEM_NOTICE"("NOTICE_ID","NOTICE_TITLE","NOTICE_TYPE","NOTICE_CONTENT","STATUS","CREATE_BY","CREATE_TIME","UPDATE_BY","UPDATE_TIME","REMARK","TOP_FLAG","ALERT_FLAG","ALERT_START_TIME","ALERT_END_TIME","NOTICE_CONTENT_TEXT") VALUES(38,'功能说明｜数据来源追溯','2',null,'1','平台运营中心',' 2026-09-29 10:55:00.000000000','qData',' 2026-11-06 09:59:26.000000000','模块功能说明',1,0,null,null,'<h2>数据来源追溯</h2><p>来源追溯展示权威主数据由哪些系统、哪些来源记录和哪些处理过程形成。</p><h3>核心能力</h3><ul><li>从权威记录追溯来源系统和原始记录。</li><li>查看匹配、归并、质量检查和审批过程。</li><li>识别最终字段值来自哪个来源。</li><li>展示来源记录接入时间和处理状态。</li><li>支持跨系统数据问题快速定位责任源头。</li></ul><p><strong>典型用法：</strong>追溯客户联系电话为何采用CRM值而非ERP值。</p>');
